  static let afternoon = ["下午好呀，喝口水，给自己充点电。", "嘿嘿，下午也陪着你呢。", "这会儿伸个懒腰吧，别一直坐着呀。", "aiya，下午的快乐也要记得签收。"]
  static func choose(_ action: String, state: inout RabbitSharedState, now: Date = .now) -> String {
    let hour = Calendar.current.component(.hour, from: now), today = RabbitStore.today(now)
    var pool: [String]
    if action == "captain" { pool = captain }
    else {
      pool = action == "wink" ? wink : action == "dizzy" ? dizzy : hop
      pool += greetings + care + playful
      pool += (6..<11).contains(hour) ? morning : (11..<15).contains(hour) ? lunch : (17..<21).contains(hour) ? evening : hour >= 21 || hour < 6 ? night : afternoon
      for item in state.snapshot.todos.filter({ ($0.completedDate ?? "").isEmpty && ($0.date ?? "") <= today }).prefix(3) {
        let title = item.title.count > 16 ? String(item.title.prefix(15)) + "…" : item.title
        pool += ["「\(title)」做完了吗？不急，我陪你。", "aiya，「\(title)」是不是还在等你呀？", "要不要先做「\(title)」？完成了再来找我嘿嘿。", "「\(title)」记得喔，一小步也算进度捏。"]
      }
      if let daily = state.snapshot.daily, daily.enabled && !daily.done {
        pool += [daily.question + " 我来轻轻问一下呀。", "今天的小约定完成了吗？做好了告诉我嘿嘿。", "每日的小事还在等你，有空的时候记得喔。", "aiya，今天的每日询问，你想好答案了吗？"]
      }
      if let weather = state.weather, weather.date == today {
        pool += ["今天 \(Int(weather.low.rounded()))～\(Int(weather.high.rounded()))°C，\(weather.advice)", "aiya，当地天气我看过啦：\(Int(weather.low.rounded()))～\(Int(weather.high.rounded()))°C。出门照顾好自己呀。"]
      }
      var seen = Set<String>(); pool = pool.filter { seen.insert($0).inserted }
      pool = pool.enumerated().map { index, value in value.hasSuffix("。") && index % 3 != 0 ? String(value.dropLast()) + (index % 3 == 1 ? "！" : "") : value }
    }
    let recent = state.pet.recent ?? []
    var available = pool.filter { !recent.contains($0) }
    if available.isEmpty { available = pool.filter { $0 != recent.last } }
    let text = available.randomElement() ?? "嘿嘿，我在这里陪着你"
    state.pet.recent = Array((recent.filter { $0 != text } + [text]).suffix(80))
    return text
  }
